// Player display names (SPEC_V2 §5, M6). Mirrors PawNoon.Core.DisplayName (Assets/PawNoon/Code/Core/Accounts.cs);
// both run the shared vectors in Tools/Parity/display_names.json.
//
// Rules: after normalisation (trim spaces, collapse runs of spaces, ASCII a-z -> A-Z) a name is 3-14 characters of
// A-Z, 0-9 and space. Checked in this order: characters, length, reserved. Guest names ("Stranger #1234") are
// generated by the database and never pass through here.

export const NAME_MIN = 3;
export const NAME_MAX = 14;

export type NameError = "too_short" | "too_long" | "bad_chars" | "reserved";
export type NameResult = { ok: true; name: string } | { ok: false; error: NameError };

/** House ghosts (supabase/seed.sql): nobody may take these exact names. */
const RESERVED_EXACT = ["DUSTY", "MARSHAL MITTENS", "OLD TOM"];
/** Names may not start with these (impersonating guests, staff, the game). */
const RESERVED_PREFIX = ["STRANGER", "ADMIN", "MODERATOR", "PAWNOON", "PAW NOON", "SUPPORT", "SYSTEM", "HOUSE GHOST"];

export function isAllowedChar(c: string): boolean {
  return (c >= "A" && c <= "Z") || (c >= "0" && c <= "9") || c === " ";
}

/** Trim spaces, collapse runs of spaces, ASCII a-z to A-Z. Other characters are kept (and refused later). */
export function normalizeDisplayName(raw: string): string {
  let out = "";
  let pendingSpace = false;
  // UTF-16 code units, like C# (length limits count the same way on both sides)
  for (let i = 0; i < raw.length; i++) {
    let c = raw[i];
    if (c === " ") {
      if (out.length > 0) pendingSpace = true;
      continue;
    }
    if (pendingSpace) {
      out += " ";
      pendingSpace = false;
    }
    if (c >= "a" && c <= "z") c = c.toUpperCase();
    out += c;
  }
  return out;
}

export function validateDisplayName(raw: unknown): NameResult {
  if (typeof raw !== "string") return { ok: false, error: "bad_chars" };
  const name = normalizeDisplayName(raw);
  for (let i = 0; i < name.length; i++) if (!isAllowedChar(name[i])) return { ok: false, error: "bad_chars" };
  if (name.length < NAME_MIN) return { ok: false, error: "too_short" };
  if (name.length > NAME_MAX) return { ok: false, error: "too_long" };
  if (RESERVED_EXACT.includes(name)) return { ok: false, error: "reserved" };
  if (RESERVED_PREFIX.some((p) => name.startsWith(p))) return { ok: false, error: "reserved" };
  return { ok: true, name };
}
